    "pregunta": "Conforme al RGPD, el interesado tendrá derecho a obtener del responsable del tratamiento la limitación del tratamiento de los datos cuando el responsable ya no necesite los datos personales para los fines del tratamiento, pero el interesado los necesite para:",
