    "pregunta": "Conforme al RGPD, la información al interesado sobre la base de una solicitud será facilitada por el responsable del tratamiento en el plazo de un mes a partir de la recepción de la solicitud. Teniendo en cuenta la complejidad y el número de solicitudes, dicho plazo será prorrogado:",
