    "tema": "TEST No° 44 La protección de datos de carácter personal. Regulación y definiciones. Principios de la protección de datos. Derechos de las personas. La Agencia Española de Protección de Datos",
    "pregunta": "Según el artículo 17 del RGPC, el interesado tendrá derecho a obtener sin dilación indebida del responsable del tratamiento la supresión de los datos personales que le con-ciernan, el cual estará obligado a suprimir sin dilación indebida los datos personales cuando concurra alguna de las circunstancias siguientes:",
